<template>
  <section class="inventory-work management-work">
    <div class="work-heading"><h2>Inventario</h2><button type="button" :disabled="loading" @click="load"><RefreshCw :size="18"/> Actualizar</button></div>
    <p v-if="error" role="alert" class="work-error">{{ error }}</p><p v-if="success" role="status">{{ success }}</p>
    <div class="inventory-filters"><label>Buscar producto o tipo<input v-model="query" type="search"></label><label>Mostrar<select v-model="filter"><option value="all">Todo el inventario</option><option value="low">Por reponer</option><option value="reserved">Con reservas</option><option value="requested">Con avisos de reposición</option></select></label></div>
    <p v-if="loading" role="status">Cargando inventario…</p><p v-else-if="!visible.length">No hay productos para esta búsqueda.</p>
    <div class="inventory-list"><article v-for="row in visible" :key="`${row.producto_id}:${row.variant}`" class="inventory-row"><div class="inventory-product"><small>{{ row.marca }}{{ row.publication_status==='draft' ? ' · Borrador' : '' }}</small><h3>{{ row.nombre }}</h3><strong v-if="row.variant">{{ row.variant }}</strong><small v-if="row.requests">{{ row.requests }} aviso(s) de reposición solicitado(s)</small></div><dl><div><dt>Disponible</dt><dd :class="{low:row.available<=threshold}">{{ row.available }}</dd></div><div><dt>Reservado</dt><dd>{{ row.reserved }}</dd></div><div><dt>En tienda*</dt><dd>{{ row.on_hand }}</dd></div><div><dt>Vendido</dt><dd>{{ row.sold }}</dd></div></dl><div class="inventory-actions"><button type="button" @click="select(row)"><PlusMinus :size="16"/> Ajustar</button><button type="button" @click="history(row)"><History :size="16"/> Historial</button></div></article></div>
    <p class="work-muted">*Disponible + reservado sin pago confirmado. Los movimientos se registran desde la activación del historial.</p>
    <div v-if="selected" class="work-overlay" @click.self="selected=null"><form class="work-dialog" role="dialog" aria-modal="true" aria-labelledby="adjust-title" @submit.prevent="adjust"><div class="work-heading"><h3 id="adjust-title">Ajustar inventario</h3><button type="button" aria-label="Cerrar ajuste" @click="selected=null"><X :size="20"/></button></div><p>{{ selected.nombre }} <strong>{{ selected.variant }}</strong></p><label>Movimiento<select v-model="movement"><option value="in">Ingresar unidades</option><option value="out">Retirar unidades</option></select></label><label>Cantidad<input v-model.number="amount" type="number" inputmode="numeric" min="1" max="100000" step="1" required></label><label>Motivo<select v-model="reason"><option>Reposición</option><option>Corrección de conteo</option><option>Muestra o regalo</option><option>Producto dañado</option><option>Otro</option></select></label><label>Nota del ajuste<input v-model.trim="note" maxlength="160" :required="reason==='Otro'"></label><p>Disponible: {{ selected.available }} → {{ selected.available+(movement==='in' ? amount : -amount) }}</p><p v-if="adjustError" role="alert" class="work-error">{{ adjustError }}</p><button class="work-primary" :disabled="saving" type="submit"><Save :size="18"/> {{ saving ? 'Guardando…' : 'Guardar ajuste' }}</button></form></div>
    <div v-if="historyTitle" class="work-overlay" @click.self="historyTitle=''" ><section class="work-dialog" role="dialog" aria-modal="true" aria-labelledby="history-title"><div class="work-heading"><h3 id="history-title">{{ historyTitle }}</h3><button type="button" aria-label="Cerrar historial" @click="historyTitle=''"><X :size="20"/></button></div><p v-if="historyLoading">Cargando movimientos…</p><p v-else-if="!movements.length">Todavía no hay movimientos registrados.</p><article v-for="entry in movements" :key="entry.id" class="history-entry"><strong>{{ entry.variant || 'Producto sin variantes' }} · {{ entry.before_qty }} → {{ entry.after_qty }}</strong><p>{{ entry.reason }}</p><small>{{ date(entry.created_at) }}</small></article></section></div>
  </section>
</template>
<script setup>
import {computed,onMounted,ref} from 'vue'
import {RefreshCw,SlidersHorizontal as PlusMinus,History,X,Save} from 'lucide-vue-next'
import {managementApi} from '../../api/index.js'
import {useAdminDialog} from './useAdminDialog.js'
const emit=defineEmits(['updated'])
const rows=ref([]),threshold=ref(3),query=ref(''),filter=ref('all'),loading=ref(false),error=ref(''),success=ref('')
const selected=ref(null),movement=ref('in'),amount=ref(1),reason=ref('Reposición'),note=ref(''),saving=ref(false),adjustError=ref('')
const historyTitle=ref(''),movements=ref([]),historyLoading=ref(false)
useAdminDialog(computed(()=>Boolean(selected.value || historyTitle.value)),()=>{selected.value=null;historyTitle.value=''})
const visible=computed(()=>rows.value.filter(r=>`${r.marca} ${r.nombre} ${r.variant}`.toLocaleLowerCase('es').includes(query.value.toLocaleLowerCase('es')) && (filter.value==='all' || filter.value==='low' && r.available<=threshold.value || filter.value==='reserved' && r.reserved>0 || filter.value==='requested' && r.requests>0)))
const date=value=>new Date(value).toLocaleString('es-CL')
async function load(){loading.value=true;error.value='';try{const {data}=await managementApi.inventory();rows.value=data.rows;threshold.value=data.low_stock_threshold}catch(e){error.value=e.response?.data?.error || 'No pudimos cargar el inventario.'}finally{loading.value=false}}
function select(row){selected.value=row;movement.value='in';amount.value=1;reason.value='Reposición';note.value='';adjustError.value=''}
async function adjust(){if(!Number.isInteger(amount.value)||amount.value<1)return; saving.value=true;adjustError.value='';try{await managementApi.adjustInventory({producto_id:selected.value.producto_id,variant:selected.value.variant,amount:movement.value==='in' ? amount.value : -amount.value,reason:`${reason.value}${note.value ? ': '+note.value : ''}`});selected.value=null;success.value='Inventario actualizado.';await load();emit('updated')}catch(e){adjustError.value=e.response?.data?.error || 'No pudimos guardar el ajuste.'}finally{saving.value=false}}
async function history(row){historyTitle.value=row.nombre;historyLoading.value=true;movements.value=[];try{const {data}=await managementApi.inventoryHistory(row.producto_id);movements.value=data}catch(e){historyTitle.value='';error.value=e.response?.data?.error || 'No pudimos cargar el historial.'}finally{historyLoading.value=false}}
onMounted(load)
</script>
<style scoped>
.inventory-filters{display:grid;grid-template-columns:2fr 1fr;gap:16px;margin:20px 0}.inventory-row{padding:20px 0;border-bottom:1px solid var(--ad-border);display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,1fr) auto;gap:20px;align-items:center}.inventory-product{display:grid;gap:6px;min-width:0}.inventory-product h3{font-size:16px;margin:0;overflow-wrap:anywhere}.inventory-product small{color:var(--ad-muted)}dl{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:8px;margin:0}dt{font-size:12px;color:var(--ad-muted)}dd{margin:8px 0 0;font-size:22px;font-weight:600}.low{color:#f0ae64}.inventory-actions{display:flex;gap:8px;flex-wrap:wrap}.history-entry{padding:14px 0;border-bottom:1px solid var(--ad-border);font-size:14px}.history-entry p{margin:8px 0}.history-entry small{color:var(--ad-muted)}@media(max-width:1000px){.inventory-row{grid-template-columns:1fr}.inventory-actions button{flex:1}.inventory-filters{grid-template-columns:1fr}dt{font-size:13px}}
</style>
